    it = iter(iterable)
    buf = []
    splits = 0

    for item in it:
        if pred(item):
            # Check if we've already reached maxsplit
            if maxsplit is not None and splits >= maxsplit:
                # No more splits - include this item and rest in final chunk
                if keep_separator:
                    # Current item was already added to buf before yielding
                    pass
                else:
                    # Need to include current item and all remaining
                    buf.extend([item])
                    for remaining_item in it:
                        buf.append(remaining_item)
                    yield buf
                    return
                yield buf
                buf = []
                splits += 1
            else:
                if keep_separator:
                    buf.append(item)
                yield buf
                buf = []
                splits += 1
        else:
            buf.append(item)

    yield buf

